    @Test("list rendering is byte-identical to the oracle's turndown")
    func listsMatchOracle() throws {
        for row in Self.exact {
            let got = try NotesText.htmlToMarkdown(row.html)
            #expect(got == row.markdown,
                    "\(row.name): oracle \(row.markdown.debugDescription), port \(got.debugDescription)")
        }
    }

    /// SECURITY (H1). Both recursions in `NotesLists` are mutually reachable, so capping only
    /// one leaves the other exploitable. Before `maxDepth`, 20k nested `<ul><li>` — 160 KB of
    /// input, well under any note-size limit — SIGSEGV'd the process by exhausting the stack.
    /// A crash here is a DoS on `notes get-markdown` / `export-notes` reachable from any note
    /// body, including a synced one the operator never authored.
    ///
    /// The assertion is that it THROWS rather than that it crashes-not: a hang or a segfault
    /// fails the run, so the only way to reach the `#expect` is a bounded, non-fatal refusal.
    ///
    /// This test is why `maxDepth` is 100 and not 500 — see the note on `NotesLists.maxDepth`.
    /// It only catches an over-large cap when run alongside the rest of the suite (worker thread,
    /// small stack); filtered to itself it runs somewhere roomier and passes either way.
    @Test("deeply nested lists are refused, not fatal")
    func depthCapRefusesInsteadOfCrashing() {
        let bomb = String(repeating: "<ul><li>", count: 20_000)
        #expect(throws: NotesLists.DepthExceeded.self) {
            _ = try NotesText.htmlToMarkdown(bomb)
        }
        // The same input must not take the whole export down: `export-notes --format md`
        // degrades per-note via `try?`, which requires the error to be catchable.
        #expect((try? NotesText.htmlToMarkdown(bomb)) == nil)
    }

    @Test("nesting just under the cap still renders")
    func justUnderCapRenders() throws {
        let n = 50   // < NotesLists.maxDepth
        let html = String(repeating: "<ul><li>x", count: n) + String(repeating: "</li></ul>", count: n)
        let md = try NotesText.htmlToMarkdown(html)
        #expect(md.hasSuffix("x"))
    }

    /// A control: the corpus must actually contain the shapes this test claims to cover. Without
    /// it, a generator that emitted an empty (or truncated) list would pass vacuously.
    @Test("corpus reach control")
    func corpusCoversTheShapes() {
        // Every corpus row must be accounted for by exactly one of the two lists. A row cannot be
        // dropped from `exact` to make this suite green without also being justified in
        // `divergent`, and the total is pinned so shrinking the corpus is a visible change.
        #expect(Self.exact.count + Self.divergent.count == 84,
                "corpus size changed: \(Self.exact.count) exact + \(Self.divergent.count) divergent")
        #expect(Set(Self.exact.map(\.name)).isDisjoint(with: Set(Self.divergent.map(\.name))))
        let names = Set(Self.exact.map(\.name))
        // `sib_*` is the family the v2 parser exists for: Apple nests a sublist as a SIBLING of
        // the `<li>`, not a child, and 62 of 133 real notes use that shape. If these ever fall out
        // of the corpus the central claim of this change goes untested.
        for required in ["ol_simple", "ul_simple", "ol_start5", "ol_startnan", "ol_in_ol",
                         "ol_deep_under10", "ol_empty_item", "ol_four_deep", "ol_nested_then_text",
                         "sib_only", "sib_first", "sib_trailing", "sib_ul_apple",
                         "sib_ol_numbering", "sib_two_deep", "sib_two_sublists",
                         // attribute-scanning rows: a `start`-suffixed attribute is not `start`,
                         // and `>` inside a quoted value does not end the tag. 7 of these 8 fail
                         // against the pre-fix scanner, which is what makes them worth keeping.
                         "attr_data_start", "attr_decoy_then_real", "attr_start_in_value",
                         "attr_gt_in_value", "attr_gt_then_start", "attr_gt_single_quoted",
                         // ECMA-262 StringToNumber boundary: the forms JS accepts (hex/octal/
                         // binary/Infinity/exponent/whitespace-as-zero) AND the ones it rejects
                         // (signed hex, lowercase infinity, trailing garbage).
                         "start_hex", "start_bin", "start_oct", "start_infinity",
                         "start_neg_infinity", "start_exp", "start_ws_only",
                         "start_neg_hex", "start_lower_infinity", "start_trailing_garbage",
                         "start_hex_big", "start_hex_baddigit", "start_bin_baddigit"] {
            #expect(names.contains(required), "corpus lost coverage of \(required)")
        }
        // The goldens must not be trivially empty. Exactly THREE legitimately are, and they are
        // named rather than counted: a list whose only item is blank (turndown's blankRule replaces
        // the item, then the wrapper's newlines are trimmed away), and the two genuinely empty
        // lists. Naming them keeps the control tight — a generator that started emitting "" for
        // everything would still fail here. This assertion has already caught one wrong assumption
        // of mine (that no golden could be empty at all), so it stays exact-set, not a count.
        let empties = Set(Self.exact.filter { $0.markdown.isEmpty }.map(\.name))
        #expect(empties == ["ul_only_blanks", "ul_empty_list", "ol_empty_list"],
                "unexpected empty goldens: \(empties.sorted())")
        // ordered markers must actually appear, or the numbering claim is untested
        #expect(Self.exact.contains { $0.markdown.contains("1.  ") })
        #expect(Self.exact.contains { $0.markdown.contains("10.  ") })
        #expect(Self.exact.contains { $0.markdown.contains("NaN.  ") })
    }

    // MARK: known divergences, deliberately NOT fixed here

    /// Each divergent row is asserted from BOTH sides: the port still produces exactly what it
    /// produced when the gap was recorded, AND it still differs from the oracle. The second
    /// assertion is the one that matters - when NOTES-L1 (or img/table rendering) lands, this goes
    /// red and forces the row to be moved into `exact` deliberately, instead of the divergence
    /// quietly persisting in a file whose name claims parity.
    @Test("known divergences still diverge, and still diverge in exactly the recorded way")
    func divergencesArePinnedFromBothSides() throws {
        for row in Self.divergent {
            let got = try NotesText.htmlToMarkdown(row.html)
            #expect(got == row.port,
                    "\(row.name): port behaviour CHANGED (now \(got.debugDescription), recorded \(row.port.debugDescription)) - if the underlying gap was closed, move this row into `exact`")
            #expect(got != row.oracle,
                    "\(row.name): port now MATCHES the oracle - the gap is closed; move this row into `exact` and drop it from `divergent`")
        }
    }
}
